<template>
  <view class="journal-editor" :class="[themeClass, {'is-preview-mode': mobileMode === 'preview'}]">
    <view class="editor-nav">
      <view class="nav-left" @tap="back"><text class="cuIcon-close"></text><text class="nav-word">退出编辑</text></view>
      <view class="nav-context"><text class="nav-kicker">见字 · 投稿编辑</text><text class="nav-journal">{{ journalName || '选择投稿刊物' }}</text></view>
      <view class="nav-actions"><text class="draft-state">{{ draftState }}</text><text class="save-draft" @tap="saveDraft">保存草稿</text><text class="submit-button" @tap="submit">提交审核</text></view>
    </view>
    <view class="mobile-switch"><text :class="{active: mobileMode === 'edit'}" @tap="mobileMode='edit'">编辑</text><text :class="{active: mobileMode === 'preview'}" @tap="mobileMode='preview'">预览</text></view>
    <view class="editor-workspace">
      <scroll-view scroll-y class="writing-column"><view class="writing-inner">
        <view class="journal-context" @tap="chooseJournal"><view class="context-mark"><text class="cuIcon-book"></text></view><view class="context-copy"><text class="context-label">投稿至</text><text class="context-name">{{ journalName || '请选择刊物' }}</text></view><text class="cuIcon-right context-arrow"></text></view>
        <view class="title-block"><text class="eyebrow">NEW STORY / {{ journalName || 'JOURNAL' }}</text><input v-model="title" @input="markChanged" class="title-input" maxlength="120" placeholder="给这篇文章一个标题" /><input v-model="subtitle" @input="markChanged" class="subtitle-input" maxlength="160" placeholder="副标题或一句话导语（可选）" /></view>
        <view class="summary-block"><text class="section-label">文章摘要 <text>可选</text></text><textarea v-model="summary" @input="markChanged" maxlength="1000" class="summary-input" placeholder="用一两句话告诉读者，这篇文章值得读什么。" /></view>
        <view class="writing-section"><view class="section-heading"><view><text class="section-label">正文</text><text class="section-note">{{ bodyLength }} 字</text></view><text class="design-link" @tap="designOpen=true"><text class="cuIcon-settings"></text> 文章设计</text></view><view class="editor-toolbar"><text @tap="insertMarkdown('## 小标题\n\n')">H2</text><text @tap="insertMarkdown('> 一句值得被留下的话\n\n')" class="toolbar-quote">❝</text><text @tap="insertMarkdown('---\n\n')">分隔线</text><text @tap="chooseCover">封面图</text><text @tap="insertMarkdown('[链接文字](https://)')">链接</text></view><textarea v-model="body" @input="markChanged" class="body-input" maxlength="60000" placeholder="从这里开始写下你的文章…\n\n可以使用标题、引用、图片和分隔线，让文章拥有自己的节奏。" /><view class="editor-foot"><text>支持 Markdown 语法</text><text>内容将由编辑部审核后发布</text></view></view>
        <view class="cover-strip" @tap="chooseCover"><image v-if="coverUrl" :src="coverUrl" mode="aspectFill"></image><view v-else class="cover-placeholder"><text class="cuIcon-cameraadd"></text></view><view><text class="cover-title">{{ coverUrl ? '更换文章封面' : '添加文章封面' }}</text><text class="cover-desc">封面会出现在文章开头，也会用于刊物列表</text></view><text class="cuIcon-right"></text></view>
      </view></scroll-view>
      <scroll-view scroll-y class="preview-column"><view class="preview-top"><view><text class="preview-kicker">LIVE PREVIEW</text><text class="preview-caption">读者看到的样子</text></view><view class="preview-tools" @tap="designOpen=true"><text class="cuIcon-settings"></text> 设计</view></view><view class="article-preview" :class="layoutClass"><image v-if="coverUrl" class="preview-cover" :src="coverUrl" mode="aspectFill"></image><view class="preview-masthead"><text>{{ journalName || '见字' }}</text><text>{{ layoutLabel }} · {{ themeLabel }}</text></view><text class="preview-eyebrow">CAMPUS EDITION</text><text class="preview-title">{{ title || '未命名文章' }}</text><text v-if="subtitle" class="preview-subtitle">{{ subtitle }}</text><view class="preview-byline"><text>见字作者</text><text>·</text><text>刚刚编辑</text></view><view class="preview-rule"></view><view class="preview-summary" v-if="summary">{{ summary }}</view><mp-html class="preview-body" :content="body || '写下正文后，这里会显示文章的真实阅读效果。'" :markdown="true" /></view><view class="preview-bottom"><text>版式 {{ layoutLabel }}</text><text>主题 {{ themeLabel }}</text><text @tap="designOpen=true">调整设计 ·</text></view></scroll-view>
    </view>
    <view v-if="designOpen" class="design-mask" @tap="designOpen=false"><view class="design-sheet" @tap.stop><view class="sheet-handle"></view><view class="sheet-heading"><text>文章设计</text><text @tap="designOpen=false" class="cuIcon-close"></text></view><text class="sheet-label">版式</text><view class="preset-grid layout-grid"><view v-for="item in layouts" :key="item.value" class="preset-card" :class="{active: layout===item.value}" @tap="layout=item.value"><view class="preset-paper" :class="'paper-'+item.value"><view class="paper-line paper-line-a"></view><view class="paper-line paper-line-b"></view><view class="paper-line paper-line-c"></view></view><text>{{ item.label }}</text><small>{{ item.desc }}</small></view></view><text class="sheet-label">主题</text><view class="theme-grid"><view v-for="item in themes" :key="item.value" class="theme-card" :class="['theme-'+item.value, {active: theme===item.value}]" @tap="theme=item.value"><view class="theme-swatch"><view class="swatch-line swatch-line-a"></view><view class="swatch-line swatch-line-b"></view></view><text>{{ item.label }}</text></view></view><view class="design-done" @tap="designOpen=false">完成</view></view></view>
  </view>
</template>

<script>
import mpHtml from '@/components/mp-html/mp-html'
import { localStorage } from '../../js_sdk/mp-storage/mp-storage/index.js'
const DRAFT_KEY = 'journalArticleDraft'
export default {
  components: { mpHtml },
  data() { return { title:'', subtitle:'', summary:'', body:'', coverUrl:'', journalId:0, journalName:'', journals:[], layout:'classic', theme:'paper', mobileMode:'edit', designOpen:false, draftState:'未保存', themes:[{value:'white',label:'极简白'},{value:'paper',label:'杂志米白'},{value:'gray',label:'纸张灰'},{value:'night',label:'深夜黑'},{value:'editorial',label:'编辑部'},{value:'custom',label:'自定义'}], layouts:[{value:'classic',label:'经典杂志',desc:'首字下沉 · 叙事感'},{value:'modern',label:'现代编辑',desc:'大标题 · 强节奏'},{value:'minimal',label:'极简阅读',desc:'窄栏 · 大留白'},{value:'photo',label:'影像叙事',desc:'大图 · 图注优先'},{value:'documentary',label:'校园纪实',desc:'引语 · 人物感'},{value:'editorial',label:'编辑部特刊',desc:'期数 · 专题感'}] } },
  computed: { bodyLength(){return String(this.body||'').replace(/\s/g,'').length}, layoutLabel(){const x=this.layouts.find(v=>v.value===this.layout);return x?x.label:'经典杂志'}, themeLabel(){const x=this.themes.find(v=>v.value===this.theme);return x?x.label:'杂志米白'}, themeClass(){return 'theme-shell-'+this.theme}, layoutClass(){return 'article-layout-'+this.layout} },
  onLoad(q){this.journalId=Number(q&&q.journalId||0);this.journalName=q&&q.journalName?decodeURIComponent(q.journalName):'';this.restoreDraft();this.loadJournals()},
  methods: {
    token(){try{return JSON.parse(localStorage.getItem('userinfo')||'{}').token||localStorage.getItem('token')||''}catch(e){return ''}},
    loadJournals(){this.$Net.request({url:this.$API.journalList(),data:{page:1,limit:50},method:'get',dataType:'json',success:r=>{this.journals=r.data&&r.data.code===1&&Array.isArray(r.data.data)?r.data.data:[]}})},
    chooseJournal(){if(!this.journals.length)return uni.showToast({title:'暂无可投稿刊物',icon:'none'});uni.showActionSheet({itemList:this.journals.map(v=>v.name),success:r=>{let x=this.journals[r.tapIndex];this.journalId=x.id;this.journalName=x.name;this.markChanged()}})},
    back(){uni.navigateBack({delta:1})}, markChanged(){this.draftState='有未保存修改'},
    insertMarkdown(v){this.body=(this.body?this.body.replace(/\s*$/,'')+'\n\n':'')+v;this.markChanged()},
    restoreDraft(){try{const d=uni.getStorageSync(DRAFT_KEY);const sameJournal=!this.journalId||Number(d&&d.journalId||0)===this.journalId;if(d&&d.body&&sameJournal){this.title=d.title||'';this.subtitle=d.subtitle||'';this.summary=d.summary||'';this.body=d.body||'';this.coverUrl=d.coverUrl||'';this.layout=d.layout||'classic';this.theme=d.theme||'paper';if(!this.journalId)this.journalId=Number(d.journalId||0);if(!this.journalName)this.journalName=d.journalName||'';this.draftState='已恢复草稿'}}catch(e){}},
    saveDraft(){uni.setStorageSync(DRAFT_KEY,{title:this.title,subtitle:this.subtitle,summary:this.summary,body:this.body,coverUrl:this.coverUrl,journalId:this.journalId,journalName:this.journalName,layout:this.layout,theme:this.theme,savedAt:Date.now()});this.draftState='草稿已保存';uni.showToast({title:'草稿已保存',icon:'none'})},
    chooseCover(){uni.chooseImage({count:1,sizeType:['compressed'],sourceType:['album','camera'],success:r=>{let path=r.tempFilePaths&&r.tempFilePaths[0];if(!path)return;uni.showLoading({title:'上传中'});uni.uploadFile({url:this.$API.upload(),filePath:path,name:'file',formData:{token:this.token()},success:response=>{try{let d=JSON.parse(response.data);if(d.code===1&&d.data&&d.data.url){this.coverUrl=d.data.url;this.markChanged()}else uni.showToast({title:d.msg||'上传失败',icon:'none'})}catch(e){uni.showToast({title:'上传响应无效',icon:'none'})}},fail:()=>uni.showToast({title:'上传失败',icon:'none'}),complete:()=>uni.hideLoading()})}})},
    submit(){if(!this.token())return uni.navigateTo({url:'/pages/user/login'});if(!this.journalId)return uni.showToast({title:'请先选择投稿刊物',icon:'none'});if(this.title.trim().length<5)return uni.showToast({title:'标题至少需要5个字',icon:'none'});if(this.body.replace(/\s/g,'').length<20)return uni.showToast({title:'正文至少需要20个字',icon:'none'});uni.showLoading({title:'提交中'});this.$Net.request({url:this.$API.journalArticleSubmit(),data:{token:this.token(),params:JSON.stringify({journalId:this.journalId,title:this.title.trim(),subtitle:this.subtitle,summary:this.summary,bodyMarkdown:this.body,coverUrl:this.coverUrl,layoutPreset:this.layout,themePreset:this.theme})},method:'post',dataType:'json',success:r=>{uni.hideLoading();if(r.data&&r.data.code===1){uni.removeStorageSync(DRAFT_KEY);uni.showModal({title:'投稿已提交',content:'文章已进入编辑部审核。',showCancel:false,success:()=>this.back()})}else uni.showToast({title:r.data&&r.data.msg||'提交失败',icon:'none'})},fail:()=>{uni.hideLoading();uni.showToast({title:'网络不太好，请稍后重试',icon:'none'})}})}
  }
}
</script>

<style scoped>
.journal-editor{--ink:#213d35;--muted:#7b8983;--line:#dbe2dc;--accent:#a56f4b;--green:#2d6656;min-height:100vh;background:#f0eee8;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.editor-nav{height:72px;box-sizing:border-box;padding:calc(18px + env(safe-area-inset-top)) 34px 12px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;border-bottom:1px solid rgba(33,61,53,.12);background:rgba(240,238,232,.88);backdrop-filter:blur(18px);position:relative;z-index:4}.nav-left,.nav-actions,.nav-context{display:flex;align-items:center}.nav-left{gap:9px;color:var(--muted);font-size:13px}.nav-left .cuIcon-close{font-size:17px}.nav-context{flex-direction:column;gap:3px}.nav-kicker,.preview-kicker,.eyebrow{font-size:9px;letter-spacing:2px;color:var(--accent);text-transform:uppercase}.nav-journal{font:18px Georgia,serif}.nav-actions{justify-content:flex-end;gap:18px;font-size:12px}.draft-state{color:#9ca7a1}.save-draft{color:#53786b}.submit-button{background:var(--green);color:#fff;padding:10px 16px;border-radius:5px}.editor-workspace{max-width:1440px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1.618fr) minmax(380px,1fr);min-height:calc(100vh - 72px)}.writing-column,.preview-column{height:calc(100vh - 72px);box-sizing:border-box}.writing-column{background:#f7f5f0;border-right:1px solid rgba(33,61,53,.1)}.writing-inner{max-width:760px;margin:0 auto;padding:58px 8.5% 100px}.journal-context{display:flex;align-items:center;gap:12px;padding:12px 0 22px;border-bottom:1px solid var(--line);cursor:pointer}.context-mark{width:31px;height:31px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#dce8df;color:var(--green);font-size:14px}.context-copy{display:flex;flex-direction:column;gap:3px}.context-label,.context-name{display:block}.context-label{font-size:10px;color:var(--muted);letter-spacing:1px}.context-name{font:17px Georgia,serif}.context-arrow{margin-left:auto;color:#91a099}.title-block